package cn.minidayz.patcher;
import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
public final class Jobs implements FilesEx.Watch {
 public interface Work{void run(Jobs j)throws Exception;}public interface Listener{void changed();}
 private static Jobs instance;public final Context ctx;public final File root;public volatile boolean busy,cancel;private boolean preserveReport;private volatile Listener listener;public JSONObject report;public volatile boolean buildTask;public JSONObject buildReport=new JSONObject();private long lastProgressUi;public String status="请选择游戏 APK 和模块包",progress="";public PatchEngine.Plan plan;public File output;public String outputLabel="";public boolean keyReady;public String apkName="未选择",moduleName="未选择";public Work pending;
 public static synchronized Jobs get(Context context){if(instance==null)instance=new Jobs(context.getApplicationContext());return instance;}
 private Jobs(Context c){ctx=c;root=new File(c.getFilesDir(),"patcher");root.mkdirs();new File(root,"outputs").mkdirs();report=new JSONObject();File f=new File(root,"report.json");try{if(f.exists())report=new JSONObject(new String(FilesEx.read(new FileInputStream(f),4194304),"UTF-8"));}catch(Exception damaged){report=new JSONObject();status="上次日志损坏，已自动重建，原输入及成功结果保留";}
  try{if("running".equals(report.optString("status"))){report.put("status","interrupted").put("error_code","E_INTERRUPTED").put("error","上次任务被系统中断，原输入和上次成功结果保留").put("diagnosis",Diagnosis.explain("E_INTERRUPTED"));status="上次任务被中断，临时文件已自动清理，可重新自动处理";}}catch(Exception ignored){}
  SharedPreferences p=ctx.getSharedPreferences("local",0);apkName=p.getString("apk_name","未选择");moduleName=p.getString("module_name","未选择");String path=p.getString("output","");try{if(path.length()>0){File o=new File(path);if(o.isFile()&&o.getCanonicalPath().startsWith(new File(root,"outputs").getCanonicalPath()+File.separator)){output=o;outputLabel=p.getString("output_label","");}}}catch(Exception ignored){}keyReady=new File(root,"key.pem").isFile();try{buildReport=new JSONObject(new String(FilesEx.read(new FileInputStream(new File(root,"build-report.json")),4194304),"UTF-8"));if(buildReport.optString("status").equals("running")){buildReport.put("status","interrupted").put("message","上次检查或构建被中断，请重新执行");}}catch(Exception ignored){}recover();save();
 }
 public void recover(){Recovery.clean(root);}
 public synchronized void listen(Listener l){listener=l;notifyUi();}public synchronized void detach(Listener l){if(listener==l)listener=null;}
 public void notifyUi(){new Handler(Looper.getMainLooper()).post(new Runnable(){public void run(){Listener l=listener;if(l!=null)l.changed();}});}
 public synchronized void save(){try{File tmp=new File(root,"report.pending");FilesEx.write(tmp,report.toString(2).getBytes("UTF-8"));FilesEx.atomic(tmp,new File(root,"report.json"));if(buildTask){buildReport=new JSONObject(report.toString());File b=new File(root,"build-report.pending");FilesEx.write(b,buildReport.toString(2).getBytes("UTF-8"));FilesEx.atomic(b,new File(root,"build-report.json"));}}catch(Exception ignored){}}
 public synchronized void stage(String s,String message){status=message;progress="";try{report.remove("progress");}catch(Exception ignored){}try{report.put("stage",s);report.put("message",message);JSONArray a=report.optJSONArray("events");if(a==null){a=new JSONArray();report.put("events",a);}if(a.length()<200)a.put(new JSONObject().put("stage",s).put("message",message).put("time_ms",System.currentTimeMillis()));}catch(Exception ignored){}save();notifyUi();}
 public void progress(long done,long total){progress=total>0?(Math.min(100,done*100/total)+"%  ["+done+" / "+total+"]"):"";try{report.put("progress",progress);}catch(Exception ignored){}long now=System.currentTimeMillis();if(now-lastProgressUi>180||done==total){lastProgressUi=now;notifyUi();}}public boolean cancelled(){return cancel;}
 public synchronized void begin(String title,Work work){if(busy)return;buildTask=title.equals("检查兼容性")||title.equals("开始本地构建")||title.equals("本地自动处理并生成APK");busy=true;preserveReport=false;cancel=false;progress="";pending=work;try{report=new JSONObject().put("format","mdz-diagnostic/1").put("installer_version","1.5.0").put("engine",PatchEngine.ENGINE).put("status","running").put("stage","start").put("started_ms",System.currentTimeMillis()).put("android_sdk",Build.VERSION.SDK_INT).put("model",Build.MODEL).put("apk_name",apkName).put("module_name",moduleName).put("key_present",keyReady);}catch(Exception ignored){}stage("start",title);Intent i=new Intent(ctx,BuildService.class);try{if(Build.VERSION.SDK_INT>=26)Context.class.getMethod("startForegroundService",Intent.class).invoke(ctx,i);else ctx.startService(i);}catch(Exception e){finish(e);}}
 public synchronized void exportTask(Work work){if(busy)return;buildTask=false;busy=true;cancel=false;preserveReport=true;pending=work;status="正在导出，诊断记录保持原样";notifyUi();try{Intent i=new Intent(ctx,BuildService.class);if(Build.VERSION.SDK_INT>=26)Context.class.getMethod("startForegroundService",Intent.class).invoke(ctx,i);else ctx.startService(i);}catch(Exception e){finish(e);}}
 public synchronized void finish(Exception error){busy=false;pending=null;if(preserveReport){preserveReport=false;status=error==null?"导出完成，原诊断记录保留":"导出失败："+error.getMessage();notifyUi();return;}try{report.put("finished_ms",System.currentTimeMillis());if(error==null){report.put("status","success");}else{String m=error.getMessage();if(m==null)m=error.getClass().getSimpleName();m=m.replace(root.getAbsolutePath(),"<private>");String code=m.startsWith("E_")?m.split("[: ]",2)[0]:"E_INTERNAL";report.put("status",cancel?"cancelled":"failed").put("error_code",code).put("error",m).put("diagnosis",Diagnosis.explain(code));FilesEx.write(new File(root,"last_failure.json"),report.toString(2).getBytes("UTF-8"));status=m+"\n"+report.getJSONObject("diagnosis").getString("action");JSONObject analysis=report.optJSONObject("compatibility_analysis");if(analysis!=null){JSONObject diff=analysis.getJSONObject("difference");status+="\n最接近档案："+analysis.getString("closest_profile")+"；变更 "+diff.getInt("changed")+"，缺失 "+diff.getInt("missing")+"，新增 "+diff.getInt("extra")+" 项。";}}}catch(Exception ignored){}save();buildTask=false;notifyUi();}
 public File file(int kind){return new File(root,kind==1?"input.apk":kind==2?"module.zip":"key.pem");}
 public PatchEngine engine()throws Exception{return new PatchEngine(FilesEx.read(ctx.getAssets().open("trust.der"),16384));}
 public void importFile(Uri uri,int kind,String displayName)throws Exception{stage("import","正在导入 "+(kind==1?"游戏 APK":kind==2?"模块包":"签名文件"));File temp=new File(root,"import.pending");InputStream in=ctx.getContentResolver().openInputStream(uri);FilesEx.require(in!=null,"E_OPEN_DOCUMENT");FileOutputStream out=new FileOutputStream(temp);java.security.MessageDigest importDigest=java.security.MessageDigest.getInstance("SHA-256");long count=0,max=kind==1?2147483647L:kind==2?536870912L:33554432L;try{byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1){FilesEx.check(this);count+=n;FilesEx.require(count<=max,"E_IMPORT_LIMIT");importDigest.update(b,0,n);out.write(b,0,n);}out.getFD().sync();}finally{in.close();out.close();}FilesEx.require(count>0,"E_EMPTY_FILE");if(kind==1){ZipFile z=new ZipFile(temp);try{Map<String,ZipEntry> entries=FilesEx.entries(z);FilesEx.require(entries.containsKey("AndroidManifest.xml")&&entries.containsKey("classes.dex"),"E_NOT_APK: 请选择完整 APK，首版不支持 APKs/XAPK 拆分包");}finally{z.close();}apkName=displayName;plan=null;ctx.getSharedPreferences("local",0).edit().putString("apk_name",displayName).commit();}else if(kind==2){JSONObject m=engine().module(temp);moduleName=m.getString("name")+" · "+m.getString("version");plan=null;ctx.getSharedPreferences("local",0).edit().putString("module_name",moduleName).commit();}else{byte[] pem=Signing.keyFromFile(temp);Signing.Identity identity=Signing.identity(pem);FilesEx.require(identity.fingerprint.equals(Signing.CERT_SHA),"E_KEY_IDENTITY: 不是当前 P 版的签名身份");FilesEx.write(temp,pem);keyReady=true;}FilesEx.atomic(temp,file(kind));OutputProvenance.imported(ctx.getSharedPreferences("local",0),kind,FilesEx.hex(importDigest.digest()),output!=null&&output.isFile());stage("imported",kind==3?"签名身份已验证，仅保存在本机私有目录":"导入完成，请检查兼容性");}
 public void inspect()throws Exception{recover();report.put("automatic_cleanup",true);plan=null;FilesEx.require(file(1).isFile()&&file(2).isFile(),"E_INPUT_MISSING: 请先选择游戏 APK 和模块包");PatchEngine e=engine();try{plan=e.inspect(file(1),file(2),this);}catch(Exception error){try{if(e.analysis!=null)report.put("compatibility_analysis",e.analysis);report.put("input_sha256",FilesEx.sha(file(1),this));report.put("module_sha256",FilesEx.sha(file(2),this));PackageInfo pi=ctx.getPackageManager().getPackageArchiveInfo(file(1).getPath(),0);if(pi!=null)report.put("input_package",pi.packageName).put("input_version",pi.versionName).put("input_version_code",pi.versionCode);ZipFile z=new ZipFile(file(1));try{JSONObject fingerprints=new JSONObject();String[] names={"AndroidManifest.xml","lib/arm64-v8a/libil2cpp.so","classes2.dex","resources.arsc","assets/bin/Data/Managed/Metadata/global-metadata.dat"};for(String n:names){ZipEntry x=z.getEntry(n);if(x!=null)fingerprints.put(n,new JSONObject().put("size",x.getSize()).put("sha256",FilesEx.hex(FilesEx.digest(z.getInputStream(x),this))));}report.put("entry_fingerprints",fingerprints);}finally{z.close();}}catch(Exception ignored){}throw error;}report.put("input_sha256",plan.apkSha).put("module_sha256",plan.moduleSha).put("profile_id",plan.profile.getString("id")).put("profile",plan.profile.getString("name")).put("target_package",plan.profile.getString("output_package")).put("target_version",plan.profile.getString("output_version"));report.put("match_mode",plan.matchMode);JSONObject history=new LocalMemory(root).get(plan.apkSha,plan.moduleSha);if(history!=null)report.put("previous_success",history);checkInstalled(plan.profile);stage("compatible",plan.matchMode.equals("exact")?"已匹配适配档案，可自动生成":"已逐文件确认兼容，打包或名称版本差异已自动处理");}
 public void checkInstalled(JSONObject profile)throws Exception{try{PackageInfo installed=ctx.getPackageManager().getPackageInfo(profile.getString("output_package"),PackageManager.GET_SIGNATURES);FilesEx.require(installed.signatures!=null&&installed.signatures.length==1&&Signing.CERT_SHA.equals(FilesEx.hex(java.security.MessageDigest.getInstance("SHA-256").digest(installed.signatures[0].toByteArray()))),"E_INSTALLED_SIGNER: 已安装共存版的签名不同，请先核对安装身份");}catch(PackageManager.NameNotFoundException absent){}}
 public void build()throws Exception{SharedPreferences prefs=ctx.getSharedPreferences("local",0);build(prefs.getString("release_name",""),prefs.getString("release_version",""));}
 public void build(String requestedName,String requestedVersion)throws Exception{inspect();FilesEx.require(keyReady,"E_KEY_MISSING: 请导入原 P 版签名 PEM 或交接 ZIP");checkInstalled(plan.profile);SharedPreferences prefs=ctx.getSharedPreferences("local",0);int installedCode=0;try{installedCode=ctx.getPackageManager().getPackageInfo(plan.profile.getString("output_package"),0).versionCode;}catch(PackageManager.NameNotFoundException absent){}PackageInfo sourceInfo=ctx.getPackageManager().getPackageArchiveInfo(file(1).getPath(),0);if(sourceInfo!=null&&sourceInfo.packageName.equals(plan.profile.getString("output_package")))installedCode=Math.max(installedCode,sourceInfo.versionCode);final ReleaseOptions release=new ReleaseOptions(requestedName.trim().length()==0?"MiniDayZ2 共存版":requestedName,requestedVersion.trim().length()==0?plan.profile.getString("output_version"):requestedVersion,ReleaseOptions.nextCode(plan.profile.getInt("output_version_code"),installedCode,prefs.getInt("last_release_code",0)));
 report.put("release_name",release.name).put("release_version",release.version).put("release_code",release.code);save();File jobs=new File(root,"jobs");jobs.mkdirs();File work=new File(jobs,"job-"+System.currentTimeMillis());final File dest=new File(root,"outputs/MiniDayZ2_"+release.version.replaceAll("[^A-Za-z0-9._-]","_")+"_"+release.code+"_"+System.currentTimeMillis()+".apk");engine().build(file(1),file(2),file(3),work,dest,this,new PatchEngine.ArchiveCheck(){public void verify(File apk,JSONObject p)throws Exception{PackageInfo info=ctx.getPackageManager().getPackageArchiveInfo(apk.getPath(),0);FilesEx.require(info!=null&&info.packageName.equals(p.getString("output_package"))&&info.versionName.equals(release.version)&&info.versionCode==release.code,"E_OUTPUT_IDENTITY: 输出 APK 的安装身份或版本不符");CharSequence label=ctx.getPackageManager().getApplicationLabel(info.applicationInfo);FilesEx.require(label!=null&&release.name.equals(label.toString()),"E_OUTPUT_LABEL: 输出软件名称不符");}},release);output=dest;outputLabel=release.name+" · "+release.version+" · "+release.code;prefs.edit().putString("output_input_sha256",plan.apkSha).putString("output_module_sha256",plan.moduleSha).putBoolean("output_provenance_known",true).putBoolean("previous_output_stale",false).putString("output",dest.getPath()).putString("output_label",outputLabel).putInt("last_release_code",release.code).commit();try{new LocalMemory(root).remember(plan,release);report.put("local_history_saved",true);}catch(Exception ignored){report.put("local_history_saved",false);}report.put("output_sha256",FilesEx.sha(dest,FilesEx.QUIET)).put("output_version",outputLabel).put("signature_verified",true);save();}
 public void export(Uri uri,boolean logs)throws Exception{File temp=new File(root,"diagnostic.pending.zip");if(logs){JSONObject snapshot; synchronized(this){snapshot=new JSONObject(report.toString());}ZipOutputStream z=new ZipOutputStream(new FileOutputStream(temp));try{if(buildReport.length()>0){z.putNextEntry(new ZipEntry("build_report.json"));z.write(buildReport.toString(2).getBytes("UTF-8"));z.closeEntry();}z.putNextEntry(new ZipEntry("report.json"));z.write(snapshot.toString(2).getBytes("UTF-8"));z.closeEntry();File failure=new File(root,"last_failure.json");if(failure.isFile()){z.putNextEntry(new ZipEntry("last_failure.json"));z.write(FilesEx.read(new FileInputStream(failure),4194304));z.closeEntry();}if(snapshot.has("compatibility_analysis")){z.putNextEntry(new ZipEntry("compatibility.json"));z.write(snapshot.getJSONObject("compatibility_analysis").toString(2).getBytes("UTF-8"));z.closeEntry();}File ai=new File(root,"ai-state.json");if(ai.isFile()){String aiText=new String(FilesEx.read(new FileInputStream(ai),2097152),"UTF-8");String apiKey=new AiSettings(ctx).secret();z.putNextEntry(new ZipEntry("ai_analysis.json"));z.write(AiClient.redact(aiText,apiKey).getBytes("UTF-8"));z.closeEntry();}for(String name:new String[]{"project-analysis.json","game-log-meta.json","game-log.txt","local-assistant.json"}){File extra=new File(root,name);if(extra.isFile()){String content=new String(FilesEx.read(new FileInputStream(extra),1048576),"UTF-8");z.putNextEntry(new ZipEntry(name));z.write(AiClient.redact(content,new AiSettings(ctx).secret()).getBytes("UTF-8"));z.closeEntry();}}z.putNextEntry(new ZipEntry("HANDOFF.txt"));String text=DiagnosticHandoff.render(snapshot,failure.isFile(),new File(root,"game-log.txt").isFile());z.write(text.getBytes("UTF-8"));z.closeEntry();}finally{z.close();}}else FilesEx.require(output!=null&&output.isFile(),"E_OUTPUT_MISSING");OutputStream out=ctx.getContentResolver().openOutputStream(uri);FilesEx.require(out!=null,"E_EXPORT_OPEN");InputStream in=new FileInputStream(logs?temp:output);try{FilesEx.copy(in,out,this);}finally{in.close();out.close();temp.delete();}}
}
